SELECT COUNT(*) FROM MISSION WHERE helper_seq = #{memberSeq}
AND MISSION_STATUS = #{missionStatus}
AND ( MISSION_TITLE LIKE CONCAT('%', #{search}, '%') OR MISSION_CONTENT LIKE CONCAT('%', #{search}, '%') )

SELECT A.MISSION_SEQ as missionSeq, A.MEMBER_SEQ as memberSeq, B.MEMBER_ID AS memberId, A.MISSION_CATEGORY as missionCategory, A.MISSION_TITLE as missionTitle, A.MISSION_CONTENT as missionContent, A.MISSION_GENDER as missionGender, A.HELPER_SEQ as helperSeq, A.MISSION_RESERVATION as missionReservation, A.MISSION_RESERVATION_DT as missionReservationDt, A.MISSION_TIME as missionTime, A.MISSION_COST as missionCost, A.MISSION_STATUS as missionStatus, DATE_FORMAT(A.MISSION_CREATE_DT, '%Y-%m-%d') as missionCreatDt FROM MISSION A, MEMBER B WHERE A.member_seq = B.member_seq AND A.HELPER_SEQ = #{searchDTO.memberSeq}
AND A.MISSION_STATUS = #{searchDTO.missionStatus}
AND ( A.MISSION_TITLE LIKE CONCAT('%', #{searchDTO.search}, '%') OR A.MISSION_CONTENT LIKE CONCAT('%', #{searchDTO.search}, '%') )
ORDER BY
A.MISSION_SEQ ASC
A.MISSION_COST DESC
A.MISSION_COST ASC
A.MISSION_SEQ DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM MISSION WHERE MEMBER_SEQ = #{memberSeq}
AND MISSION_STATUS = #{missionStatus}
AND ( MISSION_TITLE LIKE CONCAT('%', #{search}, '%') OR MISSION_CONTENT LIKE CONCAT('%', #{search}, '%') )

SELECT A.MISSION_SEQ as missionSeq, A.MEMBER_SEQ as memberSeq, B.MEMBER_ID as memberId, A.MISSION_CATEGORY as missionCategory, A.MISSION_TITLE as missionTitle, A.MISSION_CONTENT as missionContent, A.MISSION_GENDER as missionGender, A.HELPER_SEQ as helperSeq, A.MISSION_RESERVATION as missionReservation, A.MISSION_RESERVATION_DT as missionReservationDt, A.MISSION_TIME as missionTime, A.MISSION_COST as missionCost, A.MISSION_STATUS as missionStatus, date_format(A.mission_create_dt, '%Y-%m-%d') as missionCreatDt FROM MISSION A, MEMBER B WHERE A.MEMBER_SEQ = B.MEMBER_SEQ AND A.MEMBER_SEQ = #{searchDTO.memberSeq}
AND A.MISSION_STATUS = #{searchDTO.missionStatus}
AND ( A.MISSION_TITLE LIKE CONCAT('%', #{searchDTO.search}, '%') OR A.MISSION_CONTENT LIKE CONCAT('%', #{searchDTO.search}, '%') )
ORDER BY
A.MISSION_SEQ ASC
A.MISSION_COST DESC
A.MISSION_COST ASC
A.MISSION_SEQ DESC
LIMIT #{limit} OFFSET #{offset}

